import re
from datetime import date
from decimal import Decimal
from collections import defaultdict

BASE = "C:/Users/<user>/AppData/Local/Temp/prompt-evals-session-45w3a7mb/"
YEAR = 2026
MONTHS = {m: i for i, m in enumerate(['jan', 'feb', 'mar', 'apr', 'may', 'jun',
                                       'jul', 'aug', 'sep', 'oct', 'nov', 'dec'], 1)}
MONTH_NAMES = {6: 'Jun', 7: 'Jul', 8: 'Aug'}

DATE_RES = [
    ('iso', re.compile(r'\b(\d{4})-(\d{1,2})-(\d{1,2})\b')),
    ('slash', re.compile(r'\b(\d{1,2})/(\d{1,2})(?:/(\d{2,4}))?\b')),
    ('dash', re.compile(r'\b(\d{2})-(\d{2})\b')),
    ('mname', re.compile(r'\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})\b', re.I)),
]
AMOUNT_RE = re.compile(r'(-*)\$?(\d[\d,]*\.\d{2})(?!\d)')

RULES = [
    (r'prime', 'Subscriptions'),
    (r'^amazon', 'Shopping'),
    (r'netflix|spotify premium|icloud', 'Subscriptions'),
    (r'xfinity|verizon', 'Phone & internet'),
    (r'planet fitness', 'Fitness'),
    (r'spotify concert|ticketmaster|\bamc\b|bowl-o-rama|steam', 'Entertainment'),
    (r'trader joe|\baldi\b|kroger|costco|whole foods', 'Groceries'),
    (r'local coffee|starbucks|mcdonald|chipotle|panera|sushi kame|thai orchid|luigi|bagel corner|rustic tap', 'Eating out & coffee'),
    (r'\bshell\b|chevron|bp gas|jiffy lube', 'Gas & car'),
    (r'\blyft\b|\buber\b|city parking|airport parking', 'Rides & parking'),
    (r'\bdelta\b|marriott|hertz', 'Travel'),
    (r'best buy|target|old navy|\brei\b|ikea|barnes|home depot', 'Shopping'),
    (r'riverside physical|dental|\bcvs\b|walgreens', 'Health'),
    (r'\batm\b|zelle|paypal transfer|venmo', 'UNCATEGORIZED'),
]


def parse_date(kind, m):
    if kind == 'iso':
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    if kind == 'slash':
        if m.group(3) and int(m.group(3)) not in (26, 2026):
            raise ValueError('unexpected year')
        return date(YEAR, int(m.group(1)), int(m.group(2)))
    if kind == 'dash':
        return date(YEAR, int(m.group(1)), int(m.group(2)))
    return date(YEAR, MONTHS[m.group(1).lower()[:3]], int(m.group(2)))


def parse_line(text):
    dm = None
    for kind, rx in DATE_RES:
        m = rx.search(text)
        if m:
            dm = (kind, m)
            break
    amounts = list(AMOUNT_RE.finditer(text))
    if dm is None or not amounts:
        return None, 'no date or amount found'
    a = amounts[-1]
    d = parse_date(*dm)
    amt = Decimal(a.group(2).replace(',', ''))
    if a.group(1):
        amt = -amt
    s = text
    for st, en in sorted([dm[1].span(), a.span()], reverse=True):
        s = s[:st] + ' ' + s[en:]
    s = re.sub(r'\(\s*\)', ' ', s)
    s = re.sub(r'\s+', ' ', s).strip(' -|:,()')
    return (d, s, amt), None


def categorize(merchant):
    low = merchant.lower()
    for pat, cat in RULES:
        if re.search(pat, low):
            return cat
    return None


rows, problems = [], []
lines = open(BASE + 'personal_expenses.txt', encoding='utf-8').read().splitlines()
for i, line in enumerate(lines, 1):
    if i <= 2 or not line.strip():
        continue
    parsed, err = parse_line(line)
    if err:
        problems.append((i, line, err))
        continue
    d, merchant, amt = parsed
    cat = categorize(merchant)
    if cat is None:
        problems.append((i, line, 'no category rule for: ' + merchant))
        cat = 'NO RULE'
    rows.append(dict(line=i, date=d, merchant=merchant, amount=amt, cat=cat, raw=line))

print('== PARSED ROWS (%d) ==' % len(rows))
for r in rows:
    print(f"L{r['line']:<4}{r['date']}  {r['merchant'][:34]:<34} {r['amount']:>10}  {r['cat']}")

print('\n== PROBLEMS ==')
for p in problems:
    print(p)

seen = {}
for r in rows:
    key = (r['date'], r['merchant'].lower(), r['amount'])
    if key in seen:
        r['dup_of'] = seen[key]
    else:
        seen[key] = r['line']

print('\n== EXACT DUPLICATES ==')
for r in rows:
    if 'dup_of' in r:
        print(f"L{r['line']} duplicates L{r['dup_of']}: {r['raw']}")

print('\n== SAME MERCHANT + AMOUNT, DATES WITHIN 7 DAYS (not exact) ==')
for x in rows:
    for y in rows:
        if x['line'] < y['line'] and x['merchant'].lower() == y['merchant'].lower() \
           and x['amount'] == y['amount'] and 'dup_of' not in x and 'dup_of' not in y \
           and abs((x['date'] - y['date']).days) <= 7:
            print(f"L{x['line']} / L{y['line']}: {x['merchant']} {x['amount']} {x['date']} {y['date']}")

print('\n== NEGATIVE AMOUNTS ==')
for r in rows:
    if r['amount'] < 0:
        print(f"L{r['line']}: {r['raw']}")

active = [r for r in rows if 'dup_of' not in r]
cat_month = defaultdict(Decimal)
for r in active:
    cat_month[(r['cat'], r['date'].month)] += r['amount']

cats = sorted({r['cat'] for r in active if r['cat'] not in ('UNCATEGORIZED', 'NO RULE')})
months = [6, 7, 8]

print('\n== MONTHLY TOTALS BY CATEGORY (dupes excluded) ==')
print(f"{'Category':<22}" + ''.join(f"{MONTH_NAMES[m]:>12}" for m in months) + f"{'Total':>12}")
grand = defaultdict(Decimal)
for c in cats + ['UNCATEGORIZED']:
    vals = [cat_month[(c, m)] for m in months]
    for m in months:
        grand[m] += cat_month[(c, m)]
    print(f"{c:<22}" + ''.join(f"{v:>12,.2f}" for v in vals) + f"{sum(vals):>12,.2f}")
print(f"{'TOTAL':<22}" + ''.join(f"{grand[m]:>12,.2f}" for m in months) + f"{sum(grand.values()):>12,.2f}")

print('\n== BUDGET CHECK ==')
amazon = [r for r in active if r['merchant'].lower().startswith('amazon') and 'prime' not in r['merchant'].lower()]
budget = [
    ('Eating out & coffee', 'Eating out & coffee', Decimal(260)),
    ('Shopping (all retail)', 'Shopping', Decimal(1200)),
]
for label, c, target in budget:
    print(f"{label} target {target}/mo")
    for m in months:
        v = cat_month[(c, m)]
        print(f"  {MONTH_NAMES[m]}: {v:>10,.2f}  vs target {target}  diff {v - target:>+10,.2f}  {'OVER' if v > target else 'under'}")
print('Amazon only (excl. Prime):')
for m in months:
    v = sum(r['amount'] for r in amazon if r['date'].month == m)
    print(f"  {MONTH_NAMES[m]}: {v:>10,.2f}")

print('\n== MONTH-OVER-MONTH CHANGES ==')
changes = []
for c in cats:
    a, b, cc = (cat_month[(c, m)] for m in months)
    changes.append((abs(b - a), c, 'Jun->Jul', a, b, b - a))
    changes.append((abs(cc - b), c, 'Jul->Aug', b, cc, cc - b))
for _, c, lab, x, y, dlt in sorted(changes, reverse=True)[:10]:
    print(f"{c:<22} {lab}: {x:>10,.2f} -> {y:>10,.2f}  change {dlt:>+10,.2f}")

print('\n== UNCATEGORIZED ==')
for r in active:
    if r['cat'] == 'UNCATEGORIZED':
        print(f"L{r['line']} {r['date']} {r['merchant']} {r['amount']}")

print('\n== CATEGORY MERCHANTS (Eating out, Shopping) ==')
for c in ['Eating out & coffee', 'Shopping']:
    print(c)
    for r in active:
        if r['cat'] == c:
            print(f"  L{r['line']} {r['date']} {r['merchant']} {r['amount']}")

